package com.greenocean.backend;
import com.greenocean.backend.catalog.service.GrowthLibrary;
import com.greenocean.backend.catalog.repository.CatalogRepository;
import com.greenocean.backend.account.repository.AccountRepository;
import com.greenocean.backend.account.service.AccountService;
import com.greenocean.backend.auth.repository.UserRepository;
import com.greenocean.backend.auth.service.TokenService;
import com.greenocean.backend.post.service.PostService;
import com.greenocean.backend.post.dto.CreatePostRequest;
import com.greenocean.backend.post.entity.*;
import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseO2LibraryTest {
 @Autowired GrowthLibrary s;@Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired PostService posts;@Autowired CatalogRepository catalog;@Autowired AccountRepository erasure;@Autowired AccountService archives;@Autowired org.springframework.test.web.servlet.MockMvc mvc;@Autowired jakarta.persistence.EntityManager entities;
 PhaseIFixtures.Actor author,reviewer,admin,other;
 @BeforeEach void setup(){PhaseIFixtures.region(db);author=PhaseIFixtures.member(db,users,tokens);reviewer=PhaseIFixtures.member(db,users,tokens);admin=PhaseIFixtures.member(db,users,tokens);other=PhaseIFixtures.member(db,users,tokens);role(admin.id(),"ADMIN");role(reviewer.id(),"MODERATOR");for(String action:List.of("DRAFT","SUBMIT","ATTACH"))grant(author.id(),action);for(String action:List.of("REVIEW","APPROVE","PUBLISH","FEATURE","RETIRE"))grant(reviewer.id(),action);}
 void role(UUID user,String role){db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name=? ON CONFLICT DO NOTHING",user,role);}
 void grant(UUID user,String action){s.grant(admin.id(),new GrowthLibrary.Grant(user,action,"GENERAL","Synthetic isolated editorial permission",Instant.now().plusSeconds(3600)));}
 Map<String,Object> doc(String kind){var d=new LinkedHashMap<String,Object>();d.put("kind",kind);d.put("title","Synthetic learning resource 🌿");d.put("summary","General education, not personal assessment");d.put("body","An original synthetic educational lesson about choosing one manageable step. You may stop or adapt this optional activity.");d.put("language","en");d.put("scope","GENERAL");d.put("topic","Small steps");d.put("why","A general example of manageable planning");d.put("audience","ADULT");d.put("rights","Synthetic original text, reference checked only in QA");d.put("sources",List.of("https://example.org/educational-reference"));d.put("warnings",List.of());d.put("externalUrl","https://example.org/availability");d.put("creator","Synthetic QA creator");return d;}
 UUID create(){return (UUID)s.create(author.id(),new GrowthLibrary.Draft(doc("ARTICLE"),0,0)).get("resource_id");}
 GrowthLibrary.Decision decision(UUID id,String action){var r=s.editorial(author.id(),id);return new GrowthLibrary.Decision(((Number)r.get("revision")).intValue(),((Number)r.get("etag")).longValue(),action,"Synthetic exact-revision source/rights review",true,true);}
 void publish(UUID id){s.transition(author.id(),id,decision(id,"SUBMIT"));s.transition(reviewer.id(),id,decision(id,"APPROVE"));s.transition(reviewer.id(),id,decision(id,"PUBLISH"));}
 UUID post(PostVisibility visibility){return posts.create(other.id(),new CreatePostRequest("A synthetic anonymous experience about taking a small step",true,visibility,null,null,null,PostType.EXPERIENCE,null,true,"ANONYMOUS")).id();}
 @Test @Tag("malicious") void ordinaryMemberAndGroupAuthorityCannotPublishOfficialContent(){assertThatThrownBy(()->s.create(other.id(),new GrowthLibrary.Draft(doc("NOTE"),0,0))).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->s.grant(admin.id(),new GrowthLibrary.Grant(admin.id(),"APPROVE","GENERAL","Self-certification",Instant.now().plusSeconds(500)))).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("creative") void concurrentDraftRevisionIsNotSilentlyOverwritten(){UUID id=create();var changed=doc("ARTICLE");changed.put("title","changed");s.edit(author.id(),id,new GrowthLibrary.Draft(changed,1,0),false);assertThatThrownBy(()->s.edit(author.id(),id,new GrowthLibrary.Draft(doc("ARTICLE"),1,0),false)).isInstanceOf(ConflictException.class);assertThat(((Map<?,?>)s.editorial(author.id(),id).get("document")).get("title")).isEqualTo("changed");}
 @Test @Tag("malicious") void authorCannotApproveOwnSubmittedRevision(){UUID id=create();role(author.id(),"MODERATOR");grant(author.id(),"REVIEW");grant(author.id(),"APPROVE");s.transition(author.id(),id,decision(id,"SUBMIT"));assertThatThrownBy(()->s.transition(author.id(),id,decision(id,"APPROVE"))).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("malicious") void approvalTargetsExactCurrentRevision(){UUID id=create();s.transition(author.id(),id,decision(id,"SUBMIT"));var old=decision(id,"APPROVE");s.edit(author.id(),id,new GrowthLibrary.Draft(doc("ARTICLE"),1,1),true);assertThatThrownBy(()->s.transition(reviewer.id(),id,old)).isInstanceOf(ConflictException.class);assertThat(s.editorial(author.id(),id).get("state")).isEqualTo("DRAFT");}
 @Test @Tag("happy") void reviewedPublicationAndNewDraftRemainSeparate(){UUID id=create();publish(id);assertThat(s.detail(other.id(),id).get("revision")).isEqualTo(1);var changed=doc("ARTICLE");changed.put("body","A new unreviewed document must never replace the published body silently.");var row=s.editorial(author.id(),id);s.edit(author.id(),id,new GrowthLibrary.Draft(changed,1,((Number)row.get("etag")).longValue()),true);assertThat(((Map<?,?>)s.detail(other.id(),id).get("document")).get("body")).isEqualTo(doc("ARTICLE").get("body"));assertThat(s.detail(other.id(),id).get("revision")).isEqualTo(1);}
 @Test @Tag("confused") void reviewRequiresRealSourceAndRightsAttestations(){UUID id=create();s.transition(author.id(),id,decision(id,"SUBMIT"));assertThatThrownBy(()->s.transition(reviewer.id(),id,new GrowthLibrary.Decision(1,1,"APPROVE","Missing actual checks",false,true))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->s.detail(other.id(),id)).isInstanceOf(NotFoundException.class);}
 @Test @Tag("malicious") void staleOrExpiredPermissionsCannotPublishOrKeepResourcesAvailable(){UUID id=create();publish(id);db.update("UPDATE educational_permissions SET revoked_at=CURRENT_TIMESTAMP WHERE user_id=? AND action='APPROVE'",reviewer.id());assertThatThrownBy(()->s.detail(other.id(),id)).isInstanceOf(NotFoundException.class);assertThat(s.browse(other.id(),"Synthetic","","","",false,0).get("items")).asList().isEmpty();}
 @Test @Tag("malicious") void displayNameAndSeedProfessionalStatusAreNotCredentialEvidence(){assertThatThrownBy(()->s.credential(admin.id(),new GrowthLibrary.Credential(author.id(),UUID.randomUUID(),"PSYCHOLOGY","No independent application",Instant.now().plusSeconds(500)))).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->s.grant(admin.id(),new GrowthLibrary.Grant(author.id(),"SUBMIT","PSYCHOLOGY","Unsupported title",Instant.now().plusSeconds(500)))).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("malicious") void unsafeExternalSourcesAreRejected(){for(String link:List.of("javascript:alert(1)","http://example.org","https://user:secret@example.org","https://127.0.0.1/x","https://localhost/x","https://example.org/%0aheader"))assertThatThrownBy(()->GrowthLibrary.external(link)).isInstanceOf(IllegalArgumentException.class);assertThat(GrowthLibrary.external("https://example.org/منبع")).startsWith("https://example.org/");}
 @Test @Tag("happy") void privateSaveIsIdempotentAndRetiredResourcesRemainRemovable(){UUID id=create();publish(id);s.save(other.id(),id,true);s.save(other.id(),id,true);assertThat(s.browse(author.id(),"","","","",true,0).get("items")).asList().isEmpty();assertThat(s.browse(other.id(),"","","","",true,0).get("items")).asList().hasSize(1);s.transition(reviewer.id(),id,decision(id,"RETIRE"));assertThatThrownBy(()->s.detail(other.id(),id)).isInstanceOf(NotFoundException.class);assertThat(((Map<?,?>)((List<?>)s.browse(other.id(),"","","","",true,0).get("items")).getFirst()).get("available")).isEqualTo(false);s.save(other.id(),id,false);assertThat(s.browse(other.id(),"","","","",true,0).get("items")).asList().isEmpty();}
 @Test @Tag("confused") void historicalCatalogClaimsAreQuarantinedWithoutDestroyingSeeds(){db.update("INSERT INTO professional_profiles(user_id,professional_type) VALUES (?,'OTHER')",author.id());UUID legacy=db.queryForObject("INSERT INTO professional_articles(author_id,title,summary,topic,read_time_minutes,status,evidence_level,published_at) VALUES (?,'Synthetic unreviewed legacy','Unverified attribution must stay hidden','Education',1,'PUBLISHED','Synthetic unverified claim',CURRENT_TIMESTAMP) RETURNING id",UUID.class,author.id());db.update("INSERT INTO growth_resources(id,author_id,legacy_article_id) VALUES (?,?,?)",legacy,author.id(),legacy);db.update("INSERT INTO growth_resource_versions(resource_id,revision,state,document) VALUES (?,1,'LEGACY_UNREVIEWED','{}'::jsonb)",legacy);assertThat(db.queryForObject("SELECT count(*) FROM professional_articles",Integer.class)).isPositive();assertThat(catalog.articles(other.id(),"All")).isEmpty();assertThat(catalog.media(other.id(),"All")).isEmpty();assertThat(db.queryForObject("SELECT count(*) FROM growth_resource_versions WHERE state='LEGACY_UNREVIEWED'",Integer.class)).isPositive();}
 @Test @Tag("happy") void anonymousAttachmentNeedsAuthorConsentIndependentReviewAndRevocableAccess(){UUID id=create();publish(id);UUID post=post(PostVisibility.PUBLIC);assertThatThrownBy(()->s.propose(author.id(),post,new GrowthLibrary.Proposal(id,"General topic"))).isInstanceOf(ForbiddenException.class);s.preference(other.id(),post,new GrowthLibrary.Preference(true,0));UUID attachment=(UUID)s.propose(author.id(),post,new GrowthLibrary.Proposal(id,"General educational topic")).get("id");s.reviewAttachment(reviewer.id(),post,attachment,"Synthetic independent relevance review");assertThat(s.attachments(author.id(),post)).hasSize(1);String body=s.attachments(author.id(),post).toString();assertThat(body).doesNotContain(other.id().toString());s.preference(other.id(),post,new GrowthLibrary.Preference(false,1));assertThat(s.attachments(author.id(),post)).isEmpty();}
 @Test @Tag("malicious") void platformEditorDoesNotAcquireFollowerPostAccess(){UUID id=create();publish(id);UUID post=post(PostVisibility.FOLLOWERS);s.preference(other.id(),post,new GrowthLibrary.Preference(true,0));assertThatThrownBy(()->s.propose(author.id(),post,new GrowthLibrary.Proposal(id,"Not authorized"))).isInstanceOf(NotFoundException.class);assertThatThrownBy(()->s.proposals(reviewer.id(),post)).isInstanceOf(NotFoundException.class);}
 @Test @Tag("malicious") void postOrResourceRevisionChangeInvalidatesAnApprovedAssociation(){UUID id=create();publish(id);UUID post=post(PostVisibility.PUBLIC);s.preference(other.id(),post,new GrowthLibrary.Preference(true,0));UUID attachment=(UUID)s.propose(author.id(),post,new GrowthLibrary.Proposal(id,"General topic")).get("id");s.reviewAttachment(reviewer.id(),post,attachment,"Reviewed relevance");db.update("UPDATE posts SET revision=revision+1 WHERE id=?",post);assertThat(s.attachments(author.id(),post)).isEmpty();}
 @Test @Tag("happy") void rightsCoverOwnSubmissionsSavesAndEraseAssociations(){UUID id=create();publish(id);s.save(other.id(),id,true);assertThat(archives.archive(author.id()).privateWellbeing().get("educationalSubmissions")).asList().hasSize(1);assertThat(archives.archive(other.id()).privateWellbeing().get("educationalSubmissions")).asList().isEmpty();erasure.erase(author.id());assertThat(db.queryForObject("SELECT count(*) FROM growth_resources WHERE id=?",Integer.class,id)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM growth_resource_saves WHERE resource_id=?",Integer.class,id)).isZero();}
 @Test @Tag("malicious") void realHttpReviewNeedsRecentMfaAndCurrentPermission()throws Exception{UUID id=create();s.transition(author.id(),id,decision(id,"SUBMIT"));entities.clear();var current=PhaseIFixtures.session(db,users,tokens,reviewer.id());mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/growth-library/editorial/"+id+"/transitions").header("Authorization","Bearer "+current.token()).contentType("application/json").content("{\"revision\":1,\"etag\":1,\"decision\":\"APPROVE\",\"note\":\"Synthetic\",\"sourcesChecked\":true,\"rightsChecked\":true}")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isForbidden());}
 void credential(UUID who){db.update("INSERT INTO professional_profiles(user_id,professional_type,verification_status,verified_at) VALUES (?,'OTHER','VERIFIED',CURRENT_TIMESTAMP)",who);UUID verification=db.queryForObject("INSERT INTO professional_verifications(professional_user_id,status,reviewed_by,reviewed_at) VALUES (?,'APPROVED',?,CURRENT_TIMESTAMP) RETURNING id",UUID.class,who,admin.id());db.update("INSERT INTO professional_application_documents(application_id,original_name,content_type,byte_size,sha256,storage_key,scan_status,scanned_at,reviewed_by) VALUES (?,'synthetic.txt','text/plain',10,?,?,'CLEAN',CURRENT_TIMESTAMP,?)",verification,"0".repeat(64),"synthetic/"+UUID.randomUUID(),admin.id());s.credential(admin.id(),new GrowthLibrary.Credential(who,verification,"EDUCATION_SCOPE","Synthetic independently checked application reference",Instant.now().plusSeconds(3000)));}
 @Test @Tag("creative") void genuineScopedCredentialPathExpiresWithoutGrantingClinicalServices(){credential(author.id());credential(reviewer.id());for(String a:List.of("DRAFT","SUBMIT"))s.grant(admin.id(),new GrowthLibrary.Grant(author.id(),a,"EDUCATION_SCOPE","Synthetic grant",Instant.now().plusSeconds(3000)));for(String a:List.of("REVIEW","APPROVE","PUBLISH"))s.grant(admin.id(),new GrowthLibrary.Grant(reviewer.id(),a,"EDUCATION_SCOPE","Synthetic grant",Instant.now().plusSeconds(3000)));var d=doc("ARTICLE");d.put("scope","EDUCATION_SCOPE");UUID id=(UUID)s.create(author.id(),new GrowthLibrary.Draft(d,0,0)).get("resource_id");publish(id);assertThat(s.detail(other.id(),id).get("scope")).isEqualTo("EDUCATION_SCOPE");assertThat(db.queryForObject("SELECT count(*) FROM professional_care_regions WHERE professional_user_id=?",Integer.class,author.id())).isZero();db.update("UPDATE educational_credentials SET expires_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE user_id=?",author.id());assertThatThrownBy(()->s.detail(other.id(),id)).isInstanceOf(NotFoundException.class);}

 @Test @Tag("malicious") void reviewerDemotionInvalidatesCurrentReviewAuthority(){UUID id=create();s.transition(author.id(),id,decision(id,"SUBMIT"));s.transition(reviewer.id(),id,decision(id,"APPROVE"));db.update("DELETE FROM user_roles WHERE user_id=? AND role_id IN(SELECT id FROM roles WHERE name IN('ADMIN','MODERATOR'))",reviewer.id());assertThatThrownBy(()->s.transition(reviewer.id(),id,decision(id,"PUBLISH"))).isInstanceOf(ForbiddenException.class);assertThat(db.queryForObject("SELECT educational_permission_live(?,'APPROVE','GENERAL')",Boolean.class,reviewer.id())).isFalse();}

}
